}

/// What one spike run measured, both directions, for the screen and the report.
class RunReport {
  final String peerName;
  final String peerPlatform;
  final String checkCode;
  final double foundMs;
  final double connectMs;

  /// This phone → the peer, summary line.
  final String sent;

  /// One-way estimate (half the round trip), this phone → the peer.
  final double sentP50Ms;
  final double sentP95Ms;

  /// Probes of the peer → this phone that we answered; their numbers print on the peer's side.
  final int receivedProbes;

  const RunReport({
    required this.peerName,
    required this.peerPlatform,
    required this.checkCode,
    required this.foundMs,
    required this.connectMs,
    required this.sent,
    required this.sentP50Ms,
    required this.sentP95Ms,
