      peerName.hashCode ^
      peerPlatform.hashCode ^
      checkCode.hashCode ^
      foundMs.hashCode ^
      connectMs.hashCode ^
      sent.hashCode ^
      sentP50Ms.hashCode ^
      sentP95Ms.hashCode ^
      receivedProbes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RunReport &&
          runtimeType == other.runtimeType &&
          peerName == other.peerName &&
          peerPlatform == other.peerPlatform &&
          checkCode == other.checkCode &&
          foundMs == other.foundMs &&
          connectMs == other.connectMs &&
          sent == other.sent &&
          sentP50Ms == other.sentP50Ms &&
          sentP95Ms == other.sentP95Ms &&
          receivedProbes == other.receivedProbes;
}

/// A transfer in progress (about every 150 ms), and its end (`done`, with what failed and where files went).
class TransferProgress {
  final BigInt bytesDone;
  final BigInt bytesTotal;
  final int filesDone;
  final int filesTotal;
  final int failed;

  /// The file most recently started.
  final String current;
  final double bytesPerSec;
  final bool done;

  /// When done: paths that did not arrive whole.
  final List<String> failedNames;

  /// When done, receiving: where each file was saved.
  final List<String> saved;
  final double seconds;

  const TransferProgress({
    required this.bytesDone,
    required this.bytesTotal,
    required this.filesDone,
    required this.filesTotal,
    required this.failed,
    required this.current,
    required this.bytesPerSec,
    required this.done,
    required this.failedNames,
    required this.saved,
    required this.seconds,
  });

  @override
  int get hashCode =>
      bytesDone.hashCode ^
      bytesTotal.hashCode ^
      filesDone.hashCode ^
      filesTotal.hashCode ^
      failed.hashCode ^
      current.hashCode ^
      bytesPerSec.hashCode ^
      done.hashCode ^
      failedNames.hashCode ^
      saved.hashCode ^
      seconds.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TransferProgress &&
          runtimeType == other.runtimeType &&
          bytesDone == other.bytesDone &&
          bytesTotal == other.bytesTotal &&
          filesDone == other.filesDone &&
          filesTotal == other.filesTotal &&
          failed == other.failed &&
          current == other.current &&
          bytesPerSec == other.bytesPerSec &&
          done == other.done &&
          failedNames == other.failedNames &&
          saved == other.saved &&
          seconds == other.seconds;
}

